    if (data.meta.type === 'flow' && data.meta.preset === 'state') {
        const unlabeledTransition = data.edges.find(({ label }) => !label)
        if (unlabeledTransition) malformed(`edges.${unlabeledTransition.id}.label`, 'required state transition label')
    }
